let timer;const el=document.querySelector('#splash');let active=false;function dismiss(){if(!active)return;clearTimeout(timer);active=false;el.hidden=true;window.dispatchEvent(new CustomEvent('omnibloom:splash-complete',{detail:{schema:1,duration:performance.now()-window.omniSplashStarted}}))}function show(){clearTimeout(timer);active=true;el.hidden=false;el.classList.remove('run');void el.offsetWidth;el.classList.add('run');window.omniSplashStarted=performance.now();timer=setTimeout(dismiss,1400)}document.querySelector('#replay').onclick=show;window.showOmniSplash=show;window.OmniSplash={show,dismiss};window.addEventListener('pagehide',dismiss);show();
